function validate(text) {
  try {
    const obj = JSON.parse(text);
    if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
      return 'Input error: Expected a JSON object';
    }
    const keys = Object.keys(obj);
    if (keys.length !== 4) {
      return 'Input error: Expected exactly four fields';
    }
    const required = ['candidate', 'health', 'review', 'rollback'];
    for (const k of required) {
      if (!keys.includes(k)) {
        return `Input error: Missing field '${k}'`;
      }
      if (typeof obj[k] !== 'string') {
        return `Input error: Field '${k}' must be a string`;
      }
    }
    for (const k of keys) {
      if (!required.includes(k)) {
        return `Input error: Unexpected field '${k}'`;
      }
    }
    const candidate = obj.candidate;
    if (candidate.trim().length === 0) {
      return 'Input error: Candidate must contain non-whitespace text';
    }
    const health = obj.health;
    const allowedHealth = ['missing', 'failing', 'passing'];
    if (!allowedHealth.includes(health)) {
      return 'Input error: Health must be one of missing, failing, passing';
    }
    const review = obj.review;
    const allowedReview = ['pending', 'rejected', 'approved'];
    if (!allowedReview.includes(review)) {
      return 'Input error: Review must be one of pending, rejected, approved';
    }
    const gaps = [];
    if (health !== 'passing') {
      gaps.push('Health must be passing');
    }
    if (review !== 'approved') {
      gaps.push('Review must be approved');
    }
    if (obj.rollback.trim().length === 0) {
      gaps.push('Rollback step is required');
    }
    if (gaps.length === 0) {
      return '0 gaps: Ready for human review';
    }
    if (gaps.length === 1) {
      return `1 gap: ${gaps[0]}`;
    }
    return `${gaps.length} gaps: ${gaps.join('; ')}`;
  } catch (e) {
    return 'Input error: Invalid JSON';
  }
}

function handleMessage(message) {
  const {type, event, id, values} = message;
  if (type === 'init') {
    return [];
  }
  if (type === 'event' && event === 'click') {
    if (id === 'check-button') {
      const result = validate(values['input-json']);
      return [{id: 'output', text: result}];
    }
    if (id === 'load-incomplete') {
      const example = '{"candidate":"demo-42","health":"missing","review":"pending","rollback":""}';
      return [
        {id: 'input-json', value: example},
        {id: 'output', text: validate(example)}
      ];
    }
    if (id === 'load-complete') {
      const example = '{"candidate":"demo-42","health":"passing","review":"approved","rollback":"Restore demo-41"}';
      return [
        {id: 'input-json', value: example},
        {id: 'output', text: validate(example)}
      ];
    }
  }
  if (type === 'event' && (event === 'input' || event === 'change') && id === 'input-json') {
    return [];
  }
  return [];
}
;
// Wornpage runtime bridge: supplied by the server, not the model.
if (typeof validate !== 'function' || typeof handleMessage !== 'function') {
  throw new TypeError('Generated app must define validate and handleMessage.');
}
if (typeof self !== 'undefined') {
  self.onmessage = ({ data }) => {
    const patches = handleMessage(data);
    if (!Array.isArray(patches)) throw new TypeError('handleMessage must return a patch array.');
    self.postMessage({ patches });
  };
}
if (typeof module !== 'undefined') {
  module.exports = { validate, handleMessage };
}

const incompleteExample = '{"candidate":"demo-42","health":"missing","review":"pending","rollback":""}';
const completeExample = '{"candidate":"demo-42","health":"passing","review":"approved","rollback":"Restore demo-41"}';

assert.deepEqual(
  validate(incompleteExample),
  '3 gaps: Health must be passing; Review must be approved; Rollback step is required'
);
assert.deepEqual(
  validate(completeExample),
  '0 gaps: Ready for human review'
);
assert.ok(validate('{ invalid }').startsWith('Input error: '));
assert.ok(validate('{"candidate":"x","health":"passing","review":"approved"}').startsWith('Input error: '));
assert.ok(validate('{"candidate":"x","health":"passing","review":"approved","rollback":"x","extra":1}').startsWith('Input error: '));
assert.ok(validate('{"candidate":"   ","health":"passing","review":"approved","rollback":"x"}').startsWith('Input error: '));
assert.ok(validate('{"candidate":"x","health":"unknown","review":"approved","rollback":"x"}').startsWith('Input error: '));
assert.ok(validate('{"candidate":"x","health":"passing","review":"unknown","rollback":"x"}').startsWith('Input error: '));

const initialValues = { 'input-json': '' };
const initPatches = handleMessage({type:'init', values:initialValues});
assert.strictEqual(initPatches.length, 0);

const loadIncMsg = {type:'event', event:'click', id:'load-incomplete', values:initialValues};
const loadIncPatches = handleMessage(loadIncMsg);
assert.strictEqual(loadIncPatches.length, 2);
const inputPatchInc = loadIncPatches.find(p => p.id === 'input-json');
const outputPatchInc = loadIncPatches.find(p => p.id === 'output');
assert.ok(inputPatchInc);
assert.strictEqual(inputPatchInc.value, incompleteExample);
assert.ok(outputPatchInc);
assert.strictEqual(outputPatchInc.text, '3 gaps: Health must be passing; Review must be approved; Rollback step is required');

const loadCmpMsg = {type:'event', event:'click', id:'load-complete', values:initialValues};
const loadCmpPatches = handleMessage(loadCmpMsg);
assert.strictEqual(loadCmpPatches.length, 2);
const inputPatchCmp = loadCmpPatches.find(p => p.id === 'input-json');
const outputPatchCmp = loadCmpPatches.find(p => p.id === 'output');
assert.ok(inputPatchCmp);
assert.strictEqual(inputPatchCmp.value, completeExample);
assert.ok(outputPatchCmp);
assert.strictEqual(outputPatchCmp.text, '0 gaps: Ready for human review');

const valuesWithInc = { 'input-json': incompleteExample };
const checkMsgInc = {type:'event', event:'click', id:'check-button', values:valuesWithInc};
const checkPatchesInc = handleMessage(checkMsgInc);
assert.strictEqual(checkPatchesInc.length, 1);
const outPatchInc = checkPatchesInc.find(p => p.id === 'output');
assert.ok(outPatchInc);
assert.strictEqual(outPatchInc.text, '3 gaps: Health must be passing; Review must be approved; Rollback step is required');

const valuesWithCmp = { 'input-json': completeExample };
const checkMsgCmp = {type:'event', event:'click', id:'check-button', values:valuesWithCmp};
const checkPatchesCmp = handleMessage(checkMsgCmp);
assert.strictEqual(checkPatchesCmp.length, 1);
const outPatchCmp = checkPatchesCmp.find(p => p.id === 'output');
assert.ok(outPatchCmp);
assert.strictEqual(outPatchCmp.text, '0 gaps: Ready for human review');

const inputMsg = {type:'event', event:'input', id:'input-json', values:{'input-json':'some text'}};
const inputPatches = handleMessage(inputMsg);
assert.strictEqual(inputPatches.length, 0);
const changeMsg = {type:'event', event:'change', id:'input-json', values:{'input-json':'some text'}};
const changePatches = handleMessage(changeMsg);
assert.strictEqual(changePatches.length, 0);

const valuesEdited = { 'input-json': '{"candidate":"a","health":"passing","review":"approved","rollback":"x"}' };
const checkMsgEdited = {type:'event', event:'click', id:'check-button', values:valuesEdited};
const checkPatchesEdited = handleMessage(checkMsgEdited);
assert.strictEqual(checkPatchesEdited.length, 1);
const outEdited = checkPatchesEdited.find(p => p.id === 'output');
assert.ok(outEdited);
assert.strictEqual(outEdited.text, '0 gaps: Ready for human review');
